constexpr std::optional<uint32_t> numberOfFixedTargetsOf(TerminatorKind kind)
{
    switch (kind) {
    case TerminatorKind::Jump:
        return 1;
    case TerminatorKind::Branch: case TerminatorKind::TryCallInline: case TerminatorKind::TestAndBranch:
        return 2;
    case TerminatorKind::Switch: case TerminatorKind::SwitchString: case TerminatorKind::SwitchOnShape:
        return std::nullopt;
    case TerminatorKind::Return: case TerminatorKind::ReturnCall: case TerminatorKind::Throw: case TerminatorKind::Rethrow:
    case TerminatorKind::Unreachable:
        return 0;
    }
    RELEASE_ASSERT_NOT_REACHED_UNDER_CONSTEXPR_CONTEXT();
}

constexpr unsigned declaredPosition(std::optional<unsigned> position)
{
    RELEASE_ASSERT_UNDER_CONSTEXPR_CONTEXT(position);
    return *position;
}

